\label{thm:X_bad_pc}
Given
\begin{itemize}
\item a single-opcode program $P$,
\item a gas amount greater than 1,
\item the program counter set to 1,
\item the symbolic and well constrained remaining inputs of $X$.
\end{itemize}
Executing $X$ on $P$ with a fully symbolic state with the above conditions
is successful and returns an empty output with the following modifications to
the symbolic state:
\begin{itemize}
\item The parameter \texttt{returnData} is empty.
\item The \texttt{executionLength} is increased by one.
\end{itemize}

\label{def:EVM.step}
\texttt{EVM.step} orchestrates opcode execution, taking the following arguments.
\begin{itemize}
\item Amount of gas left: \texttt{fuel}
\item Cost of executing the opcode: \texttt{gasCost}
\item Opcode to be executed: \texttt{instr}
\end{itemize}

Given these arguments and an \texttt{EVM.state}, the \texttt{step} function will
perform the correspondent updates on the provided state according to the
semantics of \texttt{instr}.

\label{def:bisimulation}
Given a transition system $(S, \rightarrow)$, a binary relation $R$ on $S$ is a
bisimulation if and only if for every pair of states $(p, q)\in R$ we have:
\begin{itemize}
\item if $p \rightarrow p'$ then there is $q \rightarrow q'$ with $(p', q') \in
  R$;
\item if $q \rightarrow q'$ then there is $p \rightarrow p'$ with $(p', q') \in
  R$.
\end{itemize}

Given $p, p' \in S$, we have that $p\rightarrow p'$ if
\begin{itemize}
\item $p, p'\in S_{\text{KEVM}}$ and \texttt{Rewrites} $p$ $p'$ holds.
\item $p, p'\in S_{\text{EvmYul}}$ and executing the
  \texttt{step}[\ref{def:EVM.step}] or \texttt{X}[\ref{def:EVM.X}] function on $p$ yields $p'$.
\end{itemize}

\begin{equation}\label{eq:bisimulation-explicit1}
\forall p, p'\in S_{\text{KEVM}}\,\, \texttt{Rewrites}\,\, p \,\, p'
\Rightarrow f\bigl(\text{stateMap}(p)\bigr) = \text{stateMap}(p').
\end{equation}

\begin{equation}\label{eq:bisimulation-explicit2}
\forall q, q'\in S_{\text{EvmYul}}\,\, f(q) = q' \Rightarrow
\texttt{Rewrites}\,\, \text{stateMap}'(q)\,\, \text{stateMap}'(q').
\end{equation}
